param()
$ErrorActionPreference='Stop'
$proofRoot='C:\Sirket\ERP\evidence\ERP-CRM-PREP-20261009\private\infra'
$output=Join-Path $proofRoot 'shared-input.json'
if(Test-Path -LiteralPath $output){throw 'SHARED_INPUT_ALREADY_EXISTS'}
$old=Get-Content -LiteralPath 'C:\Sirket\ERP\runtime\ERP-STAGE04-20261008\copy-config.json' -Raw|ConvertFrom-Json -AsHashtable -Depth 100
$current=Get-Content -LiteralPath 'C:\Sirket\ERP\config\TEST-20260929-01\runtime-private.json' -Raw|ConvertFrom-Json -AsHashtable -Depth 100
$restore=Get-Content -LiteralPath (Join-Path $proofRoot 'shared-restore-comparison.json') -Raw|ConvertFrom-Json -AsHashtable
$backup=Get-Content -LiteralPath (Join-Path $proofRoot 'shared-backup.json') -Raw|ConvertFrom-Json -AsHashtable
if($restore.status -cne 'PASS' -or $restore.sourceBeforeAfterEqual -ne $true -or $restore.rawCopyMatchesSource -ne $true){throw 'SHARED_INPUT_RAW_RESTORE_NOT_PROVED'}
$cn=[Data.SqlClient.SqlConnection]::new('Server=Semih\MELISADEV;Database=MELISA_ERP_CRM_SHARED_TEST_20261009_01;Integrated Security=True;Encrypt=False;Application Name=ERP-CRM-PREP-CAPTURE')
function Rows([string]$sql){$cmd=$cn.CreateCommand();$cmd.CommandTimeout=900;$cmd.CommandText=$sql;$r=$cmd.ExecuteReader();$rows=[Collections.Generic.List[object]]::new();try{while($r.Read()){$row=[ordered]@{};for($i=0;$i -lt $r.FieldCount;$i++){$row[$r.GetName($i)]=if($r.IsDBNull($i)){$null}else{$r.GetValue($i)}};$rows.Add([pscustomobject]$row)}}finally{$r.Close();$cmd.Dispose()};return $rows.ToArray()}
function RowHash([string]$table,[string]$id){if($table -cnotin @('products','customers','suppliers','party_currency_accounts','finance_accounts') -or $id -cnotmatch '^[1-9][0-9]{0,18}$'){throw 'SHARED_ROW_HASH_SCOPE'};$rows=@(Rows "SELECT CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT x.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2) h FROM dbo.[$table] x WHERE id=$id");if($rows.Count -ne 1 -or $rows[0].h -cnotmatch '^[A-F0-9]{64}$'){throw 'SHARED_ROW_HASH_NOT_FOUND'};return $rows[0].h}
try{
 $cn.Open();$identity=@(Rows "SELECT CONVERT(nvarchar(128),SERVERPROPERTY('ServerName')) server,DB_NAME() [database]")[0]
 if($identity.server -cne 'Semih\MELISADEV' -or $identity.database -cne 'MELISA_ERP_CRM_SHARED_TEST_20261009_01'){throw 'SHARED_INPUT_IDENTITY'}
 $modules=@(Rows "SELECT SCHEMA_NAME(o.schema_id) schemaName,o.name,o.type_desc,m.definition,CAST(COALESCE(OBJECTPROPERTY(o.object_id,'ExecIsTriggerDisabled'),0) AS int) isDisabled,CAST(COALESCE(OBJECTPROPERTY(o.object_id,'ExecIsFirstInsertTrigger'),0) AS int) firstInsert,CAST(COALESCE(OBJECTPROPERTY(o.object_id,'ExecIsFirstUpdateTrigger'),0) AS int) firstUpdate,CAST(COALESCE(OBJECTPROPERTY(o.object_id,'ExecIsFirstDeleteTrigger'),0) AS int) firstDelete FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id WHERE o.is_ms_shipped=0 ORDER BY schemaName,o.name")
 $schema=@(Rows "SELECT SCHEMA_NAME(o.schema_id) schemaName,o.name tableName,c.name columnName,TYPE_NAME(c.user_type_id) typeName FROM sys.objects o JOIN sys.columns c ON c.object_id=o.object_id WHERE o.type='U' AND o.is_ms_shipped=0 ORDER BY schemaName,tableName,c.column_id")
 # Select only the previous verified finite profile, never its SQL/JWT credentials.
 $profile=$old.copyContext;$actorPermissionRows=@{}
 foreach($actor in $profile.actors){$id=$actor.id;if($id -cnotin @('15','16')){throw 'SHARED_ACTOR_SCOPE'};$row=@(Rows "SELECT u.role_id nativeRoleId,r.code nativeRoleCode FROM dbo.users u JOIN dbo.roles r ON r.id=u.role_id WHERE u.id=$id AND u.is_active=1 AND r.is_active=1");if($row.Count -ne 1 -or [string]$row[0].nativeRoleId -cne [string]$actor.nativeRoleId -or $row[0].nativeRoleCode -cne $actor.role){throw 'SHARED_EXISTING_ACTOR_CHANGED'};$actor.permissionsRowsHash=@(Rows "SELECT CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT p.* FROM dbo.permissions p WHERE p.role_id=$id ORDER BY p.id FOR JSON PATH,INCLUDE_NULL_VALUES)),2) h")[0].h;$actorPermissionRows[$id]=@(Rows "SELECT permission_key,can_view,can_create,can_update,can_approve FROM dbo.permissions WHERE role_id=$id AND (can_view=1 OR can_create=1 OR can_update=1 OR can_approve=1) ORDER BY permission_key");$actor.permissions=@()}
 foreach($p in $profile.products){if($p.id -cnotin @('29980','30003') -or $p.priceIds.Count -ne 1 -or $p.priceIds[0] -cnotmatch '^[1-9][0-9]{0,18}$'){throw 'SHARED_PRODUCT_SCOPE'};$p.beforeHash=RowHash 'products' $p.id;$row=@(Rows "SELECT stock_code,unit,CONVERT(varchar(60),CONVERT(decimal(28,8),purchase_price)) purchasePriceExact8,CONVERT(varchar(60),CONVERT(decimal(28,4),average_cost_try)) costExact4 FROM dbo.products WHERE id=$($p.id)")[0];if($row.stock_code -cne $p.stockCode -or $row.unit -cne 'ADET' -or $null -eq $row.costExact4 -or $null -eq $row.purchasePriceExact8){throw 'SHARED_PRODUCT_UNIT_OR_COST_UNKNOWN'};$p.purchasePriceExact8=$row.purchasePriceExact8;$p.costExact4=$row.costExact4;$price=@(Rows "SELECT CONVERT(varchar(60),CONVERT(decimal(28,8),price)) priceExact8 FROM dbo.product_prices WHERE id=$($p.priceIds[0]) AND product_id=$($p.id) AND price_type=N'sale' AND currency_code=N'TRY'");if($price.Count -ne 1){throw 'SHARED_SELECTED_PRICE_CHANGED'};$p.salePriceExact8=$price[0].priceExact8}
 foreach($kind in @('customers','suppliers')){foreach($p in $profile[$kind]){$p.beforeHash=RowHash $kind $p.id;$p.accountBeforeHash=RowHash 'party_currency_accounts' $p.accountId}}
 foreach($p in $profile.financeAccounts){$p.beforeHash=RowHash 'finance_accounts' $p.id;$row=@(Rows "SELECT CONVERT(varchar(60),CONVERT(decimal(28,4),opening_balance)) openingBalanceExact4,CONVERT(varchar(60),CONVERT(decimal(28,4),current_balance)) baselineBalanceExact4 FROM dbo.finance_accounts WHERE id=$($p.id) AND currency_code=N'TRY' AND is_active=1");if($row.Count -ne 1){throw 'SHARED_FINANCE_SCOPE'};$p.openingBalanceExact4=$row[0].openingBalanceExact4;$p.baselineBalanceExact4=$row[0].baselineBalanceExact4}
 $profile.baselineMaxIds=@{};$profile.baselineRowIds=@{}
 $factorySource=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'stage4-copy-sql.mjs') -Raw
 $finiteBlock=[regex]::Match($factorySource,'COPY_MUTABLE_TABLES=Object\.freeze\(\[([\s\S]*?)\]\);').Groups[1].Value
 $finiteTables=@([regex]::Matches($finiteBlock,"'([a-z_]+)'")|ForEach-Object {$_.Groups[1].Value});if($finiteTables.Count -ne 35){throw 'SHARED_FINITE_BASELINE_FACTORY_CHANGED'}
 foreach($t in ($schema|Where-Object {$_.schemaName -eq 'dbo' -and $_.tableName -cin $finiteTables}|Group-Object -Property { $_.tableName })){$name=$t.Name;if($name -cnotmatch '^[a-zA-Z0-9_]+$'){throw 'SHARED_BASELINE_TABLE_NAME'};$id=@($t.Group|Where-Object {$_.columnName -eq 'id'});$request=@($t.Group|Where-Object {$_.columnName -eq 'request_id'});if($id.Count -eq 1 -and $id[0].typeName -cin @('int','bigint')){$maxRow=@(Rows "SELECT CONVERT(varchar(20),ISNULL(MAX(id),0)) m FROM dbo.[$name]")[0];$profile.baselineMaxIds[$name]=[string]$maxRow.m}elseif($id.Count -eq 1 -or $request.Count -eq 1){$column=if($id.Count -eq 1){'id'}else{'request_id'};$profile.baselineRowIds[$name]=@(@(Rows "SELECT CONVERT(varchar(80),[$column]) v FROM dbo.[$name] ORDER BY [$column]")|ForEach-Object {$_.v})}}
 $input=[ordered]@{identity=$identity;recoveryProof=$restore;backupSHA=$backup.sha256;sourceCommit=$current.sourceCommit;profile=$profile;actorPermissionRows=$actorPermissionRows;goal7SourceVersion=$current.goal7SourceVersion;modules=$modules;schema=$schema}
 # Runtime source commit is in the immutable package manifest, not a secret config field.
 $input.sourceCommit=(Get-Content -LiteralPath 'C:\Sirket\ERP\releases\CANONICAL-STAGE04-TEST-20261009-125\release-manifest.json' -Raw|ConvertFrom-Json).sourceCommit
 foreach($key in @('catalogMediaRoot','catalogMediaIndexSha256','catalogClassificationRoot','catalogClassificationIndexSha256')){$input[$key]=$current[$key]}
 [IO.File]::WriteAllText($output,($input|ConvertTo-Json -Depth 100),[Text.UTF8Encoding]::new($false))
 @{captured=$true;moduleCount=$modules.Count;schemaColumns=$schema.Count;actors=$profile.actors.Count;products=$profile.products.Count;businessWrites=0;secretsSaved=$false}|ConvertTo-Json
}finally{$cn.Dispose()}
